// Shader by @RobinsSecret on twt

#define TWO_PI 6.28318530718
#define PI 3.14159

//  Function from Iñigo Quiles
//  https://www.shadertoy.com/view/MsS3Wc
vec3 hsb2rgb(vec3 c){
    vec3 rgb = clamp(abs(mod(c.x*6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0)
    - 1.0, 0.0, 1.0);
    rgb = rgb*rgb*(3.0-2.0*rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

vec3 drawCircleRainbow(float radius, vec2 uv, float speed){
    vec3 color = vec3(0.0);

    float angle = atan(uv.y, uv.x);
    angle += PI / 4.0 * iTime;
    color = hsb2rgb(vec3((angle/TWO_PI)+0.5, radius, 1.0));
    return color;
}

vec3 drawCircleBorder(float rCircle, float rBorder){
    vec3 color = vec3(smoothstep(rCircle, rCircle + 0.07, rBorder));
    return color;
}

vec3 drawCircleInnerBorder(float rCircle, float rBorder){
    vec3 color = vec3(smoothstep(rCircle, rCircle - 0.08, rBorder));
    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    uv = fract(uv * 1.5) - 0.5;
    vec2 mouseUV = (iMouse.xy * 2.0 - iResolution.xy) / iResolution.y;

    vec3 color = vec3(0.0);

    float radius = length(uv) * 2.0;

    float circleR = 1.0;
    float circler = 0.6;

    circleR += (cos(iTime*2.0) - 2.5) / 10.0;
    circler += (cos(iTime*2.0) - 2.5) / 10.0;

    if(distance(mouseUV, uv0) < 0.4){
        circleR -= 0.2;
        circler -= 0.2;
    }

    if(radius > circleR && radius < circleR + 0.07){
        color = drawCircleBorder(circleR, radius);
    } else if(radius < circleR && radius > circler){
        color = drawCircleRainbow(radius, uv0, 2.0);
    } else if (radius < circler){
        color = drawCircleInnerBorder(circler, radius);
    }

    fragColor = vec4(color, 1.0);
}
